async function openDetail(item){const v=++detailVersion;current=item;sources=[];resolved=null;$('detailContent').hidden=true;$('detailLoading').hidden=false;$('detailError').hidden=true;$('resolvedPanel').hidden=true;if(!$('mediaDialog').open)$('mediaDialog').showModal();try{const data=await api(`Users/${session.user}/Items/${item.Id}`,{Fields:'MediaSources,MediaStreams,Overview'});if(v!==detailVersion)return;current=data;sources=data.MediaSources||[];$('detailTitle').textContent=data.SeriesName?data.SeriesName+' · '+data.Name:data.Name;$('detailMeta').textContent=meta(data);$('detailOverview').textContent=data.Overview||'暂无剧情介绍。';$('detailPoster').hidden=false;$('detailPoster').src=img(data);$('detailPoster').onerror=()=>$('detailPoster').hidden=true;renderSourceOptions();$('detailContent').hidden=false;$('detailLoading').hidden=true;loadEngine().catch(()=>{})}catch(e){if(v===detailVersion){$('detailLoading').hidden=true;$('detailError').textContent=e.message;$('detailError').hidden=false}}}
function sourceLabel(s,index){return (s.Name||'版本 '+(index+1))+(s.Size?' · '+formatBytes(s.Size):'')}
