function sourceInput(item=current,source=$('playerDialog').open?$('playerSourceSelect').value:$('sourceSelect').value){return {server:session.server,token:session.token,user:session.user,item:String(item.Id),source:source||'',name:item.SeriesName?item.SeriesName+' - '+item.Name:item.Name}}
async function getLink(refresh=false){if(!current||!session)throw Error('没有选择视频。');const target=current.Id;const input=sourceInput();const res=await fetch('/api/media',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...input,refresh}),signal:AbortSignal.timeout(65000)});const data=await res.json();if(!res.ok)throw Error(data.error||'获取播放源失败。');if(String(current?.Id)!==String(target))throw Error('视频已切换。');resolved={...data,item:String(target),time:Date.now()};$('resolvedLink').value=data.url;$('sourceSize').textContent=formatBytes(data.size)+' · 临时播放源';$('externalLink').href=data.url;$('resolvedPanel').hidden=false;$('iinaLink').href='iina://weblink?url='+encodeURIComponent(data.url);$('vlcLink').href='vlc://'+data.url;return data}
