async function downloadCurrent(){if(!current)return;try{const mode=await ensureFolder();const sourceId=$('playerDialog').open?$('playerSourceSelect').value:$('sourceSelect').value;queue.add([{...current,sourceId}],session,mode);toast('已加入下载队列。')}catch(e){if(e.name!=='AbortError')toast(e.message)}}
function renderDownloads(q){const names={queued:'等待下载',downloading:'下载中',paused:'已暂停',done:'已完成',error:'失败',submitted:'已交给浏览器',cancelled:'已取消'};$('downloadList').innerHTML=q.jobs.length?[...q.jobs].reverse().map(j=>{const percent=j.total?Math.min(100,j.bytes/j.total*100):0;return `<div class="download-row"><span class="download-symbol">${j.status==='done'?'✓':'↓'}</span><div class="download-copy"><strong>${escape(j.name)}</strong><small>${escape(new URL(j.server).host)} · ${escape(j.username)}${j.mode==='browser'?' · 浏览器管理进度':' · '+formatBytes(j.bytes)+(j.total?' / '+formatBytes(j.total):'')}${j.error?' · '+escape(j.error):''}</small>${j.mode==='folder'?`<div class="download-progress"><i style="width:${percent}%"></i></div>`:''}</div><span class="download-state ${j.status}">${names[j.status]||j.status}${j.status==='downloading'&&j.total?' '+percent.toFixed(1)+'%':''}</span>${['error','paused','cancelled','submitted'].includes(j.status)?`<button class="secondary" data-retry="${j.id}">重试</button>`:''}${['queued','downloading','paused'].includes(j.status)?`<button class="secondary" data-cancel="${j.id}">取消</button>`:''}</div>`}).join(''):'<div class="empty"><strong>一次选好，逐集保存</strong>选中多集或点击「下载整季」，在这里管理下载任务。</div>';$('downloadList').querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>queue.retry(b.dataset.retry));$('downloadList').querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>queue.cancel(b.dataset.cancel));$('pauseQueue').disabled=q.paused;$('resumeQueue').disabled=!q.jobs.some(j=>['paused','queued'].includes(j.status))}
function loadEngine(){return loadPromise??=new Promise((resolve,reject)=>{if(window.AVPlayer){resolve(window.AVPlayer.default||window.AVPlayer);return}const script=document.createElement('script');script.src='/libmedia/avplayer.js';script.onload=()=>resolve(window.AVPlayer.default||window.AVPlayer);script.onerror=()=>{loadPromise=null;reject(Error('兼容播放器加载失败，请重试。'))};document.head.append(script)})}
