function onEnded(){savePosition();report('stop');if(session&&current)writePreference(positionKey(session,current.Id),{seconds:0,time:Date.now()});if($('autoNext').checked&&playingContext)changeEpisode(1)}
function volume(){const n=Number($('volumeBar').value);if(nativeEngine){video.volume=n;video.muted=n===0}else libPlayer?.setVolume(n);$('muteButton').textContent=n===0?'♩':'♫'}
